using System;using UnityEngine;
namespace LWS.TruckFishing.Editor {
public static class FishingFixtures {
 public static void Run(){int checks=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Fishing fixture: "+label);checks++;};var r=new FishingRules();r.Reset(1);r.Resolve(0,0,FishKind.Small,true);r.Resolve(0,1,FishKind.Large,true);check(r.caught[0]==6,"one/five pound catches");check(!r.Resolve(0,1,FishKind.Large,true)&&r.caught[0]==6,"duplicate event cannot score");r.Resolve(0,2,FishKind.Small,false);r.Resolve(0,3,FishKind.Large,false);r.Resolve(0,4,FishKind.Poison,false);check(r.missed[0]==6&&r.alive[0],"one/five pound misses and safe poison passage");r.Resolve(0,5,FishKind.Poison,true);r.FinishStep();check(!r.alive[0]&&r.Complete&&r.reason[0]=="POISON CAUGHT","poison catch eliminates immediately");r.Reset(2);for(int i=0;i<4;i++)r.Resolve(0,i,FishKind.Large,false);check(r.missed[0]==20&&!r.alive[0]&&!r.Complete,"twenty pounds eliminates before one batch result");r.FinishStep();check(r.Complete&&r.Winner==1,"last surviving participant wins once");check(!r.Resolve(1,99,FishKind.Poison,true)&&r.Winner==1,"completed result is locked");r.Reset(2);r.Resolve(0,0,FishKind.Poison,true);r.Resolve(1,0,FishKind.Poison,true);r.FinishStep();check(r.Complete&&r.Winner==-1,"same-step final eliminations produce a draw");r.Reset(1);for(int i=0;i<300;i++)r.Resolve(0,i,FishKind.Small,true);r.FinishStep();check(r.caught[0]==300&&r.alive[0]&&!r.Complete,"solo continues beyond two hundred pounds without duration cap");check(!r.Resolve(0,0,FishKind.Large,true)&&r.caught[0]==300,"ancient duplicate rejected with bounded rolling history");r.Reset(1);r.Resolve(0,100,FishKind.Small,true);check(r.Resolve(0,99,FishKind.Large,true)&&!r.Resolve(0,99,FishKind.Large,true)&&r.caught[0]==6,"out-of-order crossings resolve once");check(FishingRules.SweptCatch(2,-3,-3,2,1,-4,1.1f,out var t)&&Math.Abs(t-.4f)<.0001,"fast fish meets oppositely moving net between frames");check(!FishingRules.SweptCatch(2,-3,-3,2,3,-3,1.1f,out _),"nearby nonintersecting sweeps miss");check(!FishingRules.SweptCatch(-1,1,0,0,0,0,1.1f,out _),"upstream/backward crossing rejected");check(FishingRules.SweptCatch(10,-10,1.1f,1.1f,0,0,1.1f,out _)&&!FishingRules.SweptCatch(10,-10,1.1001f,1.1001f,0,0,1.1f,out _),"net boundary has consistent inclusive edge");var a=new FishingDirector(17381);var b=new FishingDirector(17381);double last=0;float lastX=0;FishKind lastKind=FishKind.Small;bool poison=false,breakSeen=false;for(int i=0;i<10000;i++){var x=a.Next();var y=b.Next();if(x.id!=y.id||x.kind!=y.kind||x.arrival!=y.arrival||x.travel!=y.travel||x.x!=y.x||x.curve!=y.curve)throw new Exception("Seeded schedule divergence");if(last>0&&lastKind!=FishKind.Poison&&x.kind!=FishKind.Poison&&Math.Abs(x.x-lastX)>Math.Min(4.8,8.5*Math.Max(.1,x.arrival-last-.3)*.52)+.0001)throw new Exception("Impossible consecutive good-fish spacing");if(x.arrival<=last||x.Spawn>=x.arrival||x.travel<4.5f||x.travel>8.5f||Math.Abs(x.x)>5)throw new Exception("Unsafe director timing/path");if(x.arrival<25&&x.kind==FishKind.Poison)throw new Exception("Poison in gentle opening");poison|=x.kind==FishKind.Poison;breakSeen|=x.arrival-last>3.5;float z=100;for(int step=0;step<=10;step++){var p=FishingStream.Position(x,step*.1f);if(p.z>z+.0001f||Math.Abs(p.x)>5.5f)throw new Exception("Unbounded/reversing fish path");z=p.z;}last=x.arrival;lastX=x.x;lastKind=x.kind;}check(poison&&breakSeen&&last>10000,"long-run equivalent director retains poison, recovery breaks and bounded downstream motion");Debug.Log("FISHING_RULE_FIXTURES_PASS "+checks+" assertions /10000 equivalent schedules");}
}
}
